from pathlib import Path
import json,base64
payload=json.loads('{"rag/agent_runtime/agent.py": "", "rag/agent_runtime/environment.py": "", "rag/agent_runtime/errors.py": "", "rag/agent_runtime/event_log.py": "", "rag/agent_runtime/llm.py": "", "rag/agent_runtime/observation.py": "", "rag/agent_runtime/paths.py": "", "rag/agent_runtime/permissions.py": "", "rag/agent_runtime/protocols.py": "", "rag/agent_runtime/trajectory.py": "", "rag/agent_runtime/VENDORED.json": "", "rag/agent_runtime/__init__.py": "", "rag/agent_runtime/tools/grep.py": "", "rag/agent_runtime/tools/rag.py": "", "rag/agent_runtime/tools/read_file.py": "", "rag/agent_runtime/tools/registry.py": "", "rag/agent_runtime/tools/run_tests.py": "", "rag/agent_runtime/tools/str_replace.py": "", "rag/agent_runtime/tools/__init__.py": "DQo=", "rag/service/travel_online.py": "", "rag/service/travel_agent.py": "", "rag/eval/tests/test_travel_agent.py": "", "rag/client/agent_query.py": ""}')
