from service.travel_online import OnlineTravel,CN
from datetime import datetime
from pathlib import Path
import json
p=OnlineTravel();results={}
for name,fn in [('search',lambda:p.search('龙门石窟')),('detail',lambda:p.detail(77498,'龙门石窟')),('comments',lambda:p.comments(77498,3)),('weather',lambda:p.weather('洛阳',datetime.now(CN).date().isoformat()))]:
 try:
  data=fn();results[name]={'ok':True,'result':data};print(name,'ok',len(data) if isinstance(data,list) else data.get('state'))
 except Exception as e:results[name]={'ok':False,'error':type(e).__name__,'reason':str(e)[:100]};print(name,type(e).__name__,str(e)[:100])
Path('rag/eval/reports/travel_agent_provider_probe.json').write_text(json.dumps(results,ensure_ascii=False,indent=2))
PY
